INSERT IGNORE INTO posts
  (section, slug, status, origin, title, excerpt, tag, coins, level, author, read_minutes, body, meta_description, focus_keyword, tags, featured, published_at, updated_at)
VALUES
('guias', 'o-que-e-bitcoin-de-verdade', 'published', 'manual', 'O que é bitcoin, de verdade: guia para iniciantes', 'Dinheiro digital, sem banco no meio e com oferta limitada a 21 milhões de unidades. A explicação que faltava, em linguagem simples.', NULL, '["bitcoin"]', 1, 'Redação Vibecoin', 6, '[{"type":"p","text":"Bitcoin é uma moeda digital que funciona sem banco, governo ou empresa no meio. Quem confirma as transações é uma rede de computadores espalhados pelo mundo, que seguem as mesmas regras de um programa aberto. Foi descrito em 2008 por alguém (ou algum grupo) que assinava como Satoshi Nakamoto e entrou em funcionamento em janeiro de 2009."},{"type":"h2","text":"Para que o bitcoin foi criado"},{"type":"p","text":"A ideia era permitir que duas pessoas trocassem valor pela internet sem depender de um intermediário para dizer quem tem quanto. Em um banco, o saldo é um registro que só o banco controla. No bitcoin, o registro é público e mantido por milhares de computadores ao mesmo tempo, e ninguém consegue alterá-lo sozinho."},{"type":"h2","text":"Como a rede funciona"},{"type":"p","text":"Todas as transações ficam em um livro-razão compartilhado, chamado blockchain. Ele é uma sequência de blocos: a cada cerca de 10 minutos, um novo bloco reúne as transações recentes e é encadeado ao anterior. Alterar um bloco antigo exigiria refazer todos os seguintes, o que é na prática inviável."},{"type":"p","text":"Quem organiza e confirma os blocos são os mineradores, que gastam energia e poder de computação para resolver um desafio matemático. Em troca, recebem bitcoins novos e as taxas das transações. Esse modelo se chama prova de trabalho."},{"type":"h2","text":"Por que só existirão 21 milhões"},{"type":"p","text":"O limite de 21 milhões de unidades está no código. A emissão de novos bitcoins cai pela metade a cada cerca de quatro anos, evento conhecido como halving, até chegar ao fim, que deve acontecer por volta do ano 2140. Por isso o bitcoin é chamado de ativo escasso, ao contrário da moeda de um país, que o governo pode emitir em maior quantidade."},{"type":"p","text":"Cada bitcoin pode ser dividido em até 100 milhões de partes, chamadas satoshis. Você não precisa comprar um bitcoin inteiro: dá para ter uma fração dele."},{"type":"h2","text":"O que você realmente tem quando compra bitcoin"},{"type":"p","text":"O que existe é uma chave privada, uma senha que prova que você pode movimentar certa quantidade de bitcoins registrada na rede. Quem controla a chave controla os fundos. Se você deixa suas moedas em uma corretora, é a corretora que guarda a chave por você. Entender essa diferença é o primeiro passo para ter segurança. Veja mais no guia sobre [carteiras e autocustódia](/guias/carteira-fria-quente-e-autocustodia)."},{"type":"h2","text":"O que o bitcoin não é"},{"type":"ul","items":["Não é um investimento garantido: o preço sobe e cai com força, e já houve quedas de mais de 50% em menos de um ano.","Não é anônimo: as transações são públicas, e o que fica escondido é só a identidade por trás do endereço, até que alguém a associe.","Não é emitido nem garantido por nenhum governo ou banco central.","Não rende juros por si só: só valoriza ou desvaloriza conforme a oferta e a procura."]},{"type":"h2","text":"Riscos que você precisa conhecer"},{"type":"p","text":"O preço é muito volátil, então só entre com dinheiro que você pode ficar muito tempo sem usar. Golpes são comuns: promessas de ganho fácil, robôs que prometem lucro e pedidos da sua frase de recuperação são sinais clássicos. Perder a chave privada, ou entregá-la a alguém, significa perder o dinheiro sem ninguém a quem recorrer."},{"type":"h2","text":"Próximos passos"},{"type":"ul","items":["Acompanhe a cotação em reais na [página do bitcoin](/cotacoes/bitcoin).","Simule aportes mensais com a ferramenta [simulador de aporte](/ferramentas/simulador-aporte), só para entender como o tempo e a oscilação pesam no resultado.","Leia o guia [como comprar sua primeira cripto com segurança](/guias/como-comprar-sua-primeira-cripto-com-seguranca)."]}]', 'Entenda o que é bitcoin, como a rede funciona, por que existem só 21 milhões de unidades e quais são os riscos, sem jargão e sem promessa de ganho.', 'o que é bitcoin', '["Bitcoin","Iniciante","Como funciona"]', 1, UTC_TIMESTAMP() - INTERVAL 0 DAY, UTC_TIMESTAMP()),
('guias', 'como-comprar-sua-primeira-cripto-com-seguranca', 'published', 'manual', 'Como comprar sua primeira cripto com segurança, passo a passo', 'Escolher a corretora, proteger a conta, fazer o Pix e comprar: o caminho completo, com os erros mais comuns de quem começa.', NULL, '["bitcoin"]', 1, 'Redação Vibecoin', 8, '[{"type":"p","text":"Comprar a primeira criptomoeda é simples, mas alguns cuidados no começo evitam a maior parte dos problemas. Este guia mostra o caminho, sem indicar corretora nem moeda: a escolha é sua e depende do seu objetivo e do quanto você aceita arriscar."},{"type":"h2","text":"Antes de começar"},{"type":"ul","items":["Use apenas dinheiro que você pode deixar parado por anos. Criptomoedas oscilam muito e você pode perder parte ou tudo o que colocar.","Tenha sua reserva de emergência pronta antes. Ela não deve ir para cripto.","Separe um valor pequeno para a primeira compra. Errar com R$ 100 custa pouco; errar com R$ 10 mil, não."]},{"type":"h2","text":"Passo 1: escolha uma corretora"},{"type":"p","text":"A corretora (ou exchange) é o site ou aplicativo onde você troca reais por criptomoedas. Para comparar, veja:"},{"type":"ul","items":["Se é uma empresa brasileira, com CNPJ, endereço e canal de atendimento reais. A Lei 14.478/2022 criou o marco legal do setor no Brasil, e o Banco Central foi designado como órgão supervisor das prestadoras de serviços de ativos virtuais.","Quanto cobra: taxa de negociação, spread (a diferença entre o preço de compra e o de venda) e taxa de saque.","Como deposita e saca em reais: Pix instantâneo é o padrão, e saques que demoram dias merecem desconfiança.","Segurança: verificação em duas etapas, histórico da empresa e se já houve problemas para clientes sacarem.","Quais moedas oferece, caso você tenha uma em mente."]},{"type":"p","text":"Desconfie de qualquer plataforma que prometa rendimento fixo alto e garantido. Quem promete retorno certo em cripto está, no mínimo, escondendo o risco."},{"type":"h2","text":"Passo 2: crie a conta e confirme sua identidade"},{"type":"p","text":"Corretoras regulares pedem seus dados, CPF, documento com foto e uma selfie. Esse processo, chamado KYC (conheça seu cliente), existe por causa das regras contra lavagem de dinheiro. Se um site não pede nada disso, é sinal de alerta."},{"type":"h2","text":"Passo 3: proteja a conta antes de depositar"},{"type":"ol","items":["Use uma senha longa e única, que você não usa em nenhum outro site. Um gerenciador de senhas ajuda.","Ative a verificação em duas etapas por aplicativo autenticador. Evite depender só de SMS, que pode ser desviado com o clone do chip.","Ative o código antiphishing, se a corretora oferecer. Ele aparece em todo e-mail verdadeiro dela.","Anote o endereço oficial do site e entre sempre por ele, e não por link recebido em e-mail, mensagem ou anúncio."]},{"type":"h2","text":"Passo 4: deposite por Pix"},{"type":"p","text":"Na área de depósito, escolha reais e gere o Pix para a conta da corretora. Confira se a chave ou o QR Code pertence à corretora dentro do aplicativo dela. O dinheiro costuma cair em segundos."},{"type":"h2","text":"Passo 5: faça a compra"},{"type":"p","text":"Na tela de compra, você verá, em geral, dois jeitos:"},{"type":"ul","items":["Compra a mercado (ou compra rápida): executa na hora, pelo melhor preço disponível. É mais simples, mas costuma ter spread maior.","Ordem limitada: você define o preço que aceita pagar e a ordem só executa se o mercado chegar a ele. Dá mais controle e, em geral, taxa menor, mas pode não executar."]},{"type":"p","text":"Antes de confirmar, olhe o valor total, a taxa e a quantidade que vai receber. Para começar, uma compra pequena e a mercado é suficiente."},{"type":"h2","text":"Passo 6: decida onde guardar"},{"type":"p","text":"Deixar na corretora é prático, mas quem controla a chave é a empresa. Para valores maiores ou para guardar por muito tempo, muitas pessoas preferem uma carteira própria. Leia o guia de [carteiras e autocustódia](/guias/carteira-fria-quente-e-autocustodia) antes de decidir."},{"type":"h2","text":"Erros comuns de quem começa"},{"type":"ul","items":["Comprar por impulso, depois de uma alta forte, ou por dica de rede social.","Entrar com dinheiro emprestado ou que fará falta em breve.","Mandar moedas para a rede errada ou para um endereço digitado errado. Transações em blockchain não podem ser desfeitas.","Compartilhar a tela, a senha ou o código de verificação com alguém que ofereceu ajuda. Nenhuma corretora pede esses dados.","Esquecer dos impostos: venda acima de certo valor no mês gera obrigações. Veja a seção abaixo."]},{"type":"h2","text":"E o Imposto de Renda?"},{"type":"p","text":"Comprar e manter não gera imposto, mas a posse deve ser informada na declaração anual quando passa dos valores exigidos, e o lucro na venda pode ser tributado, com isenção quando o total vendido no mês fica dentro do limite previsto na regra. Para simular o seu caso, use a [calculadora de IR sobre cripto](/ferramentas/calculadora-ir), que explica as regras vigentes e a data da última conferência."}]', 'Passo a passo para comprar sua primeira criptomoeda no Brasil: escolher a corretora, ativar a verificação em duas etapas, depositar por Pix e evitar erros.', 'como comprar criptomoedas', '["Comprar cripto","Iniciante","Segurança"]', 0, UTC_TIMESTAMP() - INTERVAL 1 DAY, UTC_TIMESTAMP()),
('guias', 'carteira-fria-quente-e-autocustodia', 'published', 'manual', 'Carteiras de cripto: fria, quente e autocustódia', 'Onde guardar suas moedas, a diferença entre cada tipo de carteira e como não perder tudo por causa de uma frase de recuperação.', NULL, '["bitcoin","ethereum"]', 2, 'Redação Vibecoin', 7, '[{"type":"p","text":"Quando você compra cripto em uma corretora, o que aparece no aplicativo é um saldo que a empresa guarda para você, como acontece com o dinheiro em um banco. Uma carteira (wallet) é a ferramenta que permite guardar as chaves por conta própria. Entender as opções ajuda a decidir quanto vale a pena cuidar do próprio dinheiro."},{"type":"h2","text":"O que é, de fato, uma carteira"},{"type":"p","text":"A carteira não guarda moedas. As moedas ficam registradas na blockchain. O que a carteira guarda são as chaves: a chave pública gera os endereços que você passa para receber, e a chave privada autoriza o envio. Quem tem a chave privada tem o controle dos fundos."},{"type":"h2","text":"Custódia e autocustódia"},{"type":"ul","items":["Custódia: uma empresa, como a corretora, guarda as chaves por você. É mais cômodo, e dá para recuperar o acesso pelo atendimento. Em compensação, você depende da empresa: se ela quebrar, for invadida ou bloquear sua conta, o dinheiro pode ficar preso.","Autocustódia: você guarda as chaves. Ninguém bloqueia seu acesso, mas ninguém recupera por você: perdeu a chave, perdeu as moedas."]},{"type":"p","text":"Existe uma frase conhecida na comunidade: se você não controla as chaves, não controla as moedas. Ela resume o argumento a favor da autocustódia, mas também o seu custo, que é a responsabilidade."},{"type":"h2","text":"Carteira quente"},{"type":"p","text":"É uma carteira conectada à internet: aplicativo no celular, extensão no navegador ou programa no computador. É prática para o uso do dia a dia, para pagar e para usar aplicativos de finanças descentralizadas. O risco é que o aparelho pode ser invadido por vírus, golpes de phishing ou aplicativos falsos."},{"type":"h2","text":"Carteira fria"},{"type":"p","text":"É uma carteira que guarda a chave privada fora da internet. O modelo mais comum é a carteira de hardware, um dispositivo parecido com um pendrive que assina as transações sem expor a chave ao computador. Também existe a carteira de papel, hoje pouco usada. É a opção mais indicada para valores grandes que você pretende guardar por muito tempo, com a desvantagem de ser menos prática e de ter um custo de compra."},{"type":"p","text":"Compre sempre direto do fabricante. Aparelhos de revendedores desconhecidos já foram adulterados."},{"type":"h2","text":"A frase de recuperação (seed phrase)"},{"type":"p","text":"Ao criar uma carteira, você recebe uma sequência de 12 ou 24 palavras. Ela é a cópia de segurança de todas as suas chaves: quem a tiver pode esvaziar sua carteira de qualquer lugar, e quem a perder não recupera as moedas se o aparelho quebrar."},{"type":"ol","items":["Anote no papel (ou grave em metal) no momento da criação. Não tire foto e não guarde em nuvem, e-mail ou bloco de notas.","Nunca digite a frase em site, formulário ou chat. Nenhuma carteira, corretora ou suporte legítimo pede essa frase.","Guarde em local seguro e, se possível, faça uma segunda cópia em outro lugar, protegida contra fogo e água.","Teste a recuperação com um valor pequeno antes de depositar quantias maiores."]},{"type":"h2","text":"Quando vale tirar da corretora"},{"type":"p","text":"Não existe resposta única. Para valores pequenos que você usa para negociar, a corretora costuma ser suficiente. Para valores que você pretende guardar por anos e cuja perda doeria, muita gente passa para a autocustódia. Uma divisão comum é manter na corretora só o que se movimenta e deixar o restante em carteira própria."},{"type":"h2","text":"Cuidados ao enviar moedas"},{"type":"ul","items":["Confira o endereço de destino inteiro, não apenas o começo e o fim: existem vírus que trocam o endereço copiado.","Verifique a rede: enviar uma moeda pela rede errada pode significar perda definitiva.","Faça um envio de teste com valor pequeno antes de transferir o total.","Desconfie de qualquer pedido de aprovação de transação que você não entende, principalmente em aplicativos descentralizados."]},{"type":"p","text":"Para saber como começar, veja o guia [como comprar sua primeira cripto com segurança](/guias/como-comprar-sua-primeira-cripto-com-seguranca)."}]', 'Entenda a diferença entre carteira quente, carteira fria e autocustódia, o que é a frase de recuperação e como guardar suas criptomoedas com mais segurança.', 'carteira de criptomoedas', '["Carteira","Autocustódia","Segurança"]', 0, UTC_TIMESTAMP() - INTERVAL 2 DAY, UTC_TIMESTAMP()),
('guias', 'stablecoins-o-que-sao-e-para-que-servem', 'published', 'manual', 'Stablecoins: o que são e para que servem', 'Moedas digitais atreladas ao dólar: como mantêm o preço, para que são usadas e quais os riscos de cada tipo.', NULL, '["tether","usdc"]', 1, 'Redação Vibecoin', 6, '[{"type":"p","text":"Stablecoin é uma criptomoeda criada para ter um preço estável, em geral atrelado a uma moeda tradicional. As mais usadas buscam valer sempre 1 dólar. Elas funcionam como ponte entre o dinheiro comum e o mundo das criptomoedas, e por isso movimentam bilhões de dólares por dia."},{"type":"h2","text":"Como mantêm o preço"},{"type":"p","text":"O valor estável não vem de mágica: depende do mecanismo que o emissor usa. Há três modelos principais:"},{"type":"ul","items":["Lastreadas em moeda tradicional: para cada token emitido, o emissor diz manter reservas equivalentes em dólar, títulos do governo americano ou dinheiro em banco. É o modelo do USDT (Tether) e do USDC.","Lastreadas em cripto: o valor é garantido por criptomoedas travadas em contratos inteligentes, em quantidade maior do que a emitida, para absorver as quedas. É o caso do DAI.","Algorítmicas: tentam manter o preço só por regras de código e incentivos, sem reservas suficientes. É o modelo mais frágil: em maio de 2022, a stablecoin algorítmica TerraUSD perdeu a paridade com o dólar e desmoronou, levando junto bilhões de dólares de investidores."]},{"type":"h2","text":"Para que servem"},{"type":"ul","items":["Mover dinheiro entre corretoras e carteiras rapidamente, a qualquer hora, inclusive em fins de semana.","Ficar fora da oscilação sem sair do mundo cripto: quem vende bitcoin e quer esperar pode manter o valor em stablecoin.","Enviar dinheiro para o exterior por taxas, em geral, menores do que as de transferências tradicionais.","Servir de base para negociar outras criptomoedas: muitos pares nas corretoras são cotados em dólar digital."]},{"type":"h2","text":"Os riscos"},{"type":"ul","items":["Risco do emissor: você depende de a empresa ter, de fato, as reservas que diz ter e de conseguir resgatá-las.","Perda da paridade (depeg): em momentos de pânico, o preço pode cair abaixo de 1 dólar, ainda que por pouco tempo.","Risco regulatório: governos de vários países discutem regras para emissores, e as exigências podem mudar.","Risco de congelamento: alguns emissores conseguem bloquear tokens de endereços específicos por ordem judicial.","Câmbio: o rendimento em dólar digital não elimina a variação do real. Ao converter de volta, o valor em reais depende da cotação do dia."]},{"type":"h2","text":"Stablecoin rende juros?"},{"type":"p","text":"A stablecoin em si não rende nada. Quando uma plataforma oferece retorno sobre ela, esse retorno vem de empréstimos ou de operações que a plataforma faz com o seu dinheiro, e traz o risco de a plataforma não pagar. Ofertas de retorno alto e fixo em dólar digital são um sinal clássico de risco."},{"type":"h2","text":"Como acompanhar"},{"type":"p","text":"Veja a cotação em reais das duas maiores nas páginas do [Tether (USDT)](/cotacoes/tether) e do [USDC](/cotacoes/usdc), e use o [conversor](/ferramentas/conversor) para calcular o valor em reais de uma quantia em dólar digital."}]', 'Entenda o que são stablecoins, como mantêm o valor atrelado ao dólar, para que servem, os tipos que existem e os riscos de perder a paridade.', 'o que são stablecoins', '["Stablecoins","Dólar","Iniciante"]', 0, UTC_TIMESTAMP() - INTERVAL 3 DAY, UTC_TIMESTAMP());
